		fmt.Fprintf(os.Stderr, "Error generating parameters: %v\n", err)
		os.Exit(1)
	}

	// Generate private key
	privateKey, err := dsa.GenerateKey(rand.Reader, params)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error generating private key: %v\n", err)
		os.Exit(1)
	}

	// Marshal private key to PEM
	pemBlock := &pem.Block{
		Type:  "DSA PRIVATE KEY",
		Bytes: privateKey.Marshal(),
	}
	pemBytes, _ := pem.EncodeToMemory(pemBlock)

	// Print PEM output
	fmt.Println(string(pemBytes))
}
